#include <algorithm>

using namespace std;

const double eps = 1e-8;
const double PI = acos(-1.0);

struct Point {
    double x, y;
    Point() : x(0), y(0) {}
    Point(double x, double y) : x(x), y(y) {}

    Point add(const Point& o) const {
        return Point(x + o.x, y + o.y);
    }

    Point sub(const Point& o) const {
        return Point(x - o.x, y - o.y);
    }

    Point rotate(double alpha) const {
        double c = cos(alpha);
        double s = sin(alpha);
        return Point(x * c - y * s, x * s + y * c);
    }

    Point norm() const {
        double len = length();
        return scale(1.0 / len);
    }

    Point scale(double f) const {
        return Point(f * x, f * y);
    }

    double length() const {
        return sqrt(x * x + y * y);
    }

    bool operator==(const Point& o) const {
        return fabs(x - o.x) < eps && fabs(y - o.y) < eps;
    }

    bool operator<(const Point& o) const {
        if (fabs(x - o.x) > eps) return x < o.x;
        if (fabs(y - o.y) > eps) return y < o.y;
        return false;
    }
};

struct Circle {
    Point o;
    double r;

    bool contains(const Point& p) const {
        double dist = p.sub(o).length();
        return fabs(dist - r) < eps;
    }
};

vector<Point> intersect(const Circle& c1, const Circle& c2) {
    double dx = c1.o.x - c2.o.x;
    double dy = c1.o.y - c2.o.y;
    double d = sqrt(dx * dx + dy * dy);
    double cos_angle = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d);
    if (cos_angle < -1 - eps) return {};
    if (cos_angle < -1) cos_angle = -1;
    if (cos_angle > 1 + eps) return {};
    if (cos_angle > 1) cos_angle = 1;
    double alpha = acos(cos_angle);
    Point dir = c2.o.sub(c1.o).norm();
    vector<Point> res;
    res.push_back(c1.o.add(dir.scale(c1.r).rotate(+alpha)));
    res.push_back(c1.o.add(dir.scale(c1.r).rotate(-alpha)));
    return res;
}

class FastScanner {
    istringstream iss;
    string line;
public:
    FastScanner() {}

    int nextInt() {
        while (iss.eof()) {
            getline(cin, line);
            iss.clear();
            iss.str(line);
        }
        int val;
        iss >> val;
        return val;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    FastScanner in;
    int n = in.nextInt();
    vector<Circle> circles(n);
    for (int i = 0; i < n; ++i) {
        int x = in.nextInt();
        int y = in.nextInt();
        int r = in.nextInt();
        circles[i].o = Point(x, y);
        circles[i].r = r;
    }

    // Collect all intersection points
    vector<Point> allList;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            vector<Point> inter = intersect(circles[i], circles[j]);
            if (!inter.empty()) {
                allList.insert(allList.end(), inter.begin(), inter.end());
            }
        }
    }
    set<Point> all(allList.begin(), allList.end());

    map<Point, int> pointId;
    vector<set<int>> adj;

    for (int i = 0; i < n; ++i) {
        // Build angles
        set<double> angles;
        const int K = 100;
        for (int j = 0; j < K; ++j) {
            angles.insert(2 * PI * j / K);
        }
        for (const Point& p : all) {
            if (circles[i].contains(p)) {
                double dx = p.x - circles[i].o.x;
                double dy = p.y - circles[i].o.y;
                double alpha = atan2(dy, dx);
                if (alpha < 0) alpha += 2 * PI;
                angles.insert(alpha);
            }
        }

        vector<double> as(angles.begin(), angles.end());
        Point dir(circles[i].r, 0);

        // Assign IDs
        for (double a : as) {
            Point p = circles[i].o.add(dir.rotate(a));
            if (pointId.find(p) == pointId.end()) {
                int sz = pointId.size();
                pointId[p] = sz;
                adj.emplace_back();
            }
        }

        // Add edges
        int m = as.size();
        for (int j = 0; j < m; ++j) {
            Point p = circles[i].o.add(dir.rotate(as[j]));
            Point q = circles[i].o.add(dir.rotate(as[(j + 1) % m]));
            int u = pointId[p];
            int v = pointId[q];
            if (u == v) continue;
            adj[u].insert(v);
            adj[v].insert(u);
        }
    }

    int V = adj.size();
    int E = 0;
    for (const auto& s : adj) {
        E += s.size();
    }
    E /= 2;

    // BFS for components
    int comps = 0;
    vector<bool> was(V, false);
    queue<int> q;
    for (int i = 0; i < V; ++i) {
        if (!was[i]) {
            ++comps;
            q.push(i);
            was[i] = true;
            while (!q.empty()) {
                int cur = q.front(); q.pop();
                for (int j : adj[cur]) {
                    if (!was[j]) {
                        was[j] = true;
                        q.push(j);
                    }
                }
            }
        }
    }

    cout << 1 + comps + E - V << endl;

    return 0;
}
